def _dispatch_with(*keys):
    """Return a minimal dispatch dict containing the given $-prefixed keys."""
    return {k: f"<span>{k[1:]}</span>" for k in keys}


class TestUndollaredCheckCapVariants(unittest.TestCase):
    """Unit tests: _check_no_undollared raises for capitalized bare accent names."""

    def _flat(self, text):
        return [text]

    def test_tsinnor_capitalized_raises(self):
        dispatch = _dispatch_with("$Tsinnor")
        with self.assertRaises(ValueError):
            dollar_sub_g._check_no_undollared(
                dispatch, self._flat("Tsinnor variation.")
            )

    def test_qamats_capitalized_raises(self):
        dispatch = _dispatch_with("$Qamats")
        with self.assertRaises(ValueError):
            dollar_sub_g._check_no_undollared(dispatch, self._flat("Qamats variation."))

    def test_dexi_ascii_raises(self):
        dispatch = _dispatch_with("$Dexi")
        with self.assertRaises(ValueError):
            dollar_sub_g._check_no_undollared(dispatch, self._flat("Dexi variation."))

    def test_dollared_tsinnor_does_not_raise(self):
        dispatch = _dispatch_with("$Tsinnor")
        # Should not raise — the bare word is not present
        dollar_sub_g._check_no_undollared(dispatch, self._flat("$Tsinnor variation."))

    def test_dollared_qamats_does_not_raise(self):
        dispatch = _dispatch_with("$Qamats")
        dollar_sub_g._check_no_undollared(dispatch, self._flat("$Qamats variation."))


