class TestIssue169TokenPresence(unittest.TestCase):
    def test_issue_169_tokens_exist(self):
        tokens = (
            "$parashah",
            "$Parashah",
            "$petuxah",
            "$Petuxah",
            "$setumah",
            "$Setumah",
            "$galgal",
            "$Galgal",
            "$yby",
            "$Yby",
        )
        for token in tokens:
            rendered = author.dollar_sub(token)
            self.assertIsNotNone(rendered)


